const bakeryData = [
  { id: 1, german: "das Brot", plural: "die Brote", arabic: "خبز", img: "https://images.unsplash.com/photo-1509440159596-0249088772ff?w=250&q=80" },
  { id: 2, german: "das Brötchen", plural: "die Brötchen", arabic: "خبز صغير (رغيف فينو/سمون)", img: "https://images.unsplash.com/photo-1589367920969-ab8e050bbb04?w=250&q=80" },
  { id: 3, german: "der Kuchen", plural: "die Kuchen", arabic: "كعكة / تورتة", img: "https://images.unsplash.com/photo-1578985545062-69928b1d9587?w=250&q=80" },
  { id: 4, german: "das Croissant", plural: "die Croissants", arabic: "كرواسون", img: "https://images.unsplash.com/photo-1555507036-ab1f4038808a?w=250&q=80" },
  { id: 5, german: "der Donut", plural: "die Donuts", arabic: "دونات", img: "https://images.unsplash.com/photo-1551024709-8f23befc6f87?w=250&q=80" },
  { id: 6, german: "das Gebäck", plural: "die Gebäcke", arabic: "معجنات / مخبوزات مشكلة", img: "https://images.unsplash.com/photo-1509440159596-0249088772ff?w=250&q=80" },
  { id: 7, german: "die Brezel", plural: "die Brezeln", arabic: "خبز البريتزل (المجدل)", img: "https://images.unsplash.com/photo-1612240498036-15f1f7d14d87?w=250&q=80" },
  { id: 8, german: "der Muffin", plural: "die Muffins", arabic: "مافن / كب كيك", img: "https://images.unsplash.com/photo-1587314168485-3236d6710814?w=250&q=80" },
  { id: 9, german: "die Torte", plural: "die Torten", arabic: "تورتة عيد ميلاد/طبقات", img: "https://images.unsplash.com/photo-1535141192574-5d4897c13136?w=250&q=80" },
  { id: 10, german: "das Baguette", plural: "die Baguettes", arabic: "خبز باجيت فرنسي", img: "https://images.unsplash.com/photo-1549931319-a545dcf3bc73?w=250&q=80" },
  { id: 11, german: "der Keks", plural: "die Kekse", arabic: "بسكويت", img: "https://images.unsplash.com/photo-1558961363-fa8fdf82db35?w=250&q=80" },
  { id: 12, german: "die Semmel", plural: "die Semmeln", arabic: "خبز أبيض دائري", img: "https://images.unsplash.com/photo-1589367920969-ab8e050bbb04?w=250&q=80" },
  { id: 13, german: "das Laugenbrezel", plural: "die Laugenbrezeln", arabic: "بريتزل بالقلويات", img: "https://images.unsplash.com/photo-1612240498036-15f1f7d14d87?w=250&q=80" },
  { id: 14, german: "der Stollen", plural: "die Stollen", arabic: "خبز شتوي بالفواكه المجففة", img: "https://images.unsplash.com/photo-1509440159596-0249088772ff?w=250&q=80" },
  { id: 15, german: "die Schnecke", plural: "die Schnecken", arabic: "معجنات حلزونية بالقرفة", img: "https://images.unsplash.com/photo-1509440159596-0249088772ff?w=250&q=80" },
  { id: 16, german: "das Soufflé", plural: "die Soufflés", arabic: "سوفليه", img: "https://images.unsplash.com/photo-1578985545062-69928b1d9587?w=250&q=80" },
  { id: 17, german: "der Plundergebäck", plural: "die Plundergebäcke", arabic: "معجنات هشة طبقات (بلندر)", img: "https://images.unsplash.com/photo-1555507036-ab1f4038808a?w=250&q=80" },
  { id: 18, german: "die Waffel", plural: "die Waffeln", arabic: "وافل", img: "https://images.unsplash.com/photo-1562243014-992a548bb146?w=250&q=80" },
  { id: 19, german: "das Vollkornbrot", plural: "die Vollkornbrote", arabic: "خبز الحبة الكاملة (أسود)", img: "https://images.unsplash.com/photo-1586444248902-2f64eddc13df?w=250&q=80" },
  { id: 20, german: "der Zopf", plural: "die Zöpfe", arabic: "خبز مجدول حلو", img: "https://images.unsplash.com/photo-1509440159596-0249088772ff?w=250&q=80" },
  { id: 21, german: "das Roggenbrot", plural: "die Roggenbrote", arabic: "خبز الجودار (الراي)", img: "https://images.unsplash.com/photo-1586444248902-2f64eddc13df?w=250&q=80" },
  { id: 22, german: "die Schrippe", plural: "die Schrippen", arabic: "خبز برلين الصغير", img: "https://images.unsplash.com/photo-1589367920969-ab8e050bbb04?w=250&q=80" },
  { id: 23, german: "die Nussecke", plural: "die Nussecke", arabic: "بسكويت مثلثات المكسرات", img: "https://images.unsplash.com/photo-1558961363-fa8fdf82db35?w=250&q=80" },
  { id: 24, german: "das Kartoffelbrot", plural: "die Kartoffelbrote", arabic: "خبز البطاطس", img: "https://images.unsplash.com/photo-1509440159596-0249088772ff?w=250&q=80" }
];

export default function BakeryPage() {
  const [searchTerm, setSearchTerm] = useState('');

  const speakGerman = (text) => {
    if ('speechSynthesis' in window && text) {
      window.speechSynthesis.cancel();
      const utterance = new SpeechSynthesisUtterance(text);
      utterance.lang = 'de-DE';
      utterance.rate = 0.8;
      window.speechSynthesis.speak(utterance);
    }
  };

  const getArticleStyle = (text, isPlural = false) => {
    const match = text.trim().match(/^(der|das|die)\s+(.*)$/i);
    if (!match) {
      return { article: '', word: text, color: '#888', bgBadge: '#f3f4f6' };
    }
    const article = match[1].toLowerCase();
    const word = match[2];

    if (article === 'der') {
      return { article: 'der', word, color: '#00bfff', bgBadge: '#e0f7ff' };
    } else if (article === 'das') {
      return { article: 'das', word, color: '#22c55e', bgBadge: '#dcfce7' };
    } else if (article === 'die') {
      return isPlural
        ? { article: 'die', word, color: '#f97316', bgBadge: '#ffedd5' }
        : { article: 'die', word, color: '#ec4899', bgBadge: '#fce7f3' };
    }
    return { article: '', word: text, color: '#888', bgBadge: '#f3f4f6' };
  };

  const filteredBakery = bakeryData.filter((item) => {
    return (
      item.german.toLowerCase().includes(searchTerm.toLowerCase()) ||
      (item.plural && item.plural.toLowerCase().includes(searchTerm.toLowerCase())) ||
      item.arabic.includes(searchTerm)
    );
  });

  return (
    <div style={{ padding: '10px 10px 40px 10px', color: 'inherit', background: 'transparent', boxSizing: 'border-box', width: '100%' }}>
      <style>{`
        .page-container {
          background: transparent;
          width: 100%;
          max-width: 500px;
          margin: 0 auto;
          box-sizing: border-box;
        }

        .page-title {
          text-align: center;
          font-size: 1.3rem;
          font-weight: 900;
          margin-bottom: 15px;
          color: inherit;
        }

        .search-container {
          display: flex;
          justify-content: center;
          margin-bottom: 12px;
        }

        .search-input {
          width: 100%;
          padding: 8px 14px;
          border-radius: 20px;
          border: 1.5px solid currentColor;
          background: transparent;
          color: inherit;
          font-size: 0.9rem;
          outline: none;
          box-sizing: border-box;
          direction: rtl;
        }

        .articles-legend {
          display: flex;
          justify-content: center;
          flex-wrap: wrap;
          gap: 10px;
          font-size: 0.72rem;
          font-weight: bold;
          margin-bottom: 12px;
        }

        .legend-item {
          display: flex;
          align-items: center;
          gap: 4px;
        }

        .legend-dot {
          width: 8px;
          height: 8px;
          border-radius: 50%;
          display: inline-block;
        }

        .cards-grid {
          display: grid;
          grid-template-columns: repeat(2, 1fr);
          gap: 12px;
          width: 100%;
          direction: ltr;
        }

        .single-card {
          position: relative;
          background-color: #ffffff;
          border-radius: 30px 6px;
          padding: 12px 8px 14px 8px;
          display: flex;
          flex-direction: column;
          align-items: center;
          text-align: center;
          box-shadow: 0 4px 10px rgba(0, 0, 0, 0.08);
          box-sizing: border-box;
          cursor: pointer;
          transition: transform 0.15s ease;
          user-select: none;
        }

        .single-card:active {
          transform: scale(0.97);
        }

        .card-top-bar {
          position: relative;
          width: 100%;
          display: flex;
          justify-content: center;
          align-items: center;
          margin-bottom: 10px;
          height: 22px;
        }

        .article-pill {
          padding: 2px 14px;
          border-radius: 12px;
          font-size: 0.72rem;
          font-weight: 800;
          text-transform: uppercase;
          letter-spacing: 0.5px;
        }

        .speaker-btn {
          position: absolute;
          right: 4px;
          top: 50%;
          transform: translateY(-50%);
          font-size: 1rem;
          color: #9ca3af;
          display: flex;
          align-items: center;
          justify-content: center;
        }

        .img-wrapper {
          width: 90px;
          height: 90px;
          border-radius: 16px;
          background-color: #ffffff;
          box-shadow: 0 2px 8px rgba(0, 0, 0, 0.06);
          display: flex;
          align-items: center;
          justify-content: center;
          overflow: hidden;
          margin-bottom: 10px;
        }

        .item-image {
          width: 100%;
          height: 100%;
          object-fit: cover;
        }

        .german-singular {
          font-size: 0.95rem;
          font-weight: 800;
          font-style: italic;
          line-height: 1.3;
          direction: ltr;
        }

        .german-plural {
          font-size: 0.85rem;
          font-weight: 800;
          font-style: italic;
          line-height: 1.3;
          margin-top: 2px;
          direction: ltr;
        }

        .arabic-word {
          font-size: 0.82rem;
          font-weight: bold;
          color: #555555;
          margin-top: 6px;
          direction: rtl;
        }
      `}</style>

      <div className="page-container">
        <h1 className="page-title">In der Bäckerei (المخبوزات)</h1>

        <div className="search-container">
          <input
            type="text"
            placeholder="ابحث عن مخبوزات ألمانية أو عربية..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="search-input"
          />
        </div>

        <div className="articles-legend" dir="rtl">
          <span className="legend-item"><span className="legend-dot" style={{ backgroundColor: '#00bfff' }}></span> der (مذكر)</span>
          <span className="legend-item"><span className="legend-dot" style={{ backgroundColor: '#22c55e' }}></span> das (محايد)</span>
          <span className="legend-item"><span className="legend-dot" style={{ backgroundColor: '#ec4899' }}></span> die (مفرد مؤنث)</span>
          <span className="legend-item"><span className="legend-dot" style={{ backgroundColor: '#f97316' }}></span> die (جمع)</span>
        </div>

        <div className="cards-grid">
          {filteredBakery.map((item) => {
            const singularInfo = getArticleStyle(item.german, false);
            const pluralInfo = item.plural ? getArticleStyle(item.plural, true) : null;

            return (
              <div
                key={item.id}
                className="single-card"
                style={{ border: `2.5px solid ${singularInfo.color}` }}
                onClick={() => speakGerman(item.plural ? `${item.german}, ${item.plural}` : item.german)}
              >
                <div className="card-top-bar">
                  {singularInfo.article && (
                    <span
                      className="article-pill"
                      style={{
                        color: singularInfo.color,
                        backgroundColor: singularInfo.bgBadge
                      }}
                    >
                      {singularInfo.article}
                    </span>
                  )}
                  <span className="speaker-btn">🔊</span>
                </div>

                <div className="img-wrapper">
                  <img src={item.img} alt={item.arabic} className="item-image" />
                </div>

                <div className="german-singular">
                  <span style={{ color: singularInfo.color }}>{singularInfo.article}</span>{' '}
                  <span style={{ color: '#000000' }}>{singularInfo.word}</span>
                </div>

                {pluralInfo && (
                  <div className="german-plural">
                    <span style={{ color: '#f97316' }}>{pluralInfo.article}</span>{' '}
                    <span style={{ color: '#000000' }}>{pluralInfo.word}</span>
                  </div>
                )}

                <div className="arabic-word">{item.arabic}</div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}