export default function AllAdjectivesPage() {
  const [searchTerm, setSearchTerm] = useState('');

  const speakGerman = (text) => {
    if ('speechSynthesis' in window && text) {
      window.speechSynthesis.cancel();
      const utterance = new SpeechSynthesisUtterance(text);
      utterance.lang = 'de-DE';
      utterance.rate = 0.8; // صوت بطيء وواضح
      window.speechSynthesis.speak(utterance);
    }
  };

  // دالة لاستخراج الأداة ولونها وتنسيق الشارة (Badge)
  const getArticleStyle = (text, isPlural = false) => {
    const match = text.trim().match(/^(der|das|die)\s+(.*)$/i);
    if (!match) {
      return { article: '', word: text, color: '#888', bgBadge: '#f3f4f6' };
    }
    const article = match[1].toLowerCase();
    const word = match[2];

    if (article === 'der') {
      return { article: 'der', word, color: '#00bfff', bgBadge: '#e0f7ff' };
    } else if (article === 'das') {
      return { article: 'das', word, color: '#22c55e', bgBadge: '#dcfce7' };
    } else if (article === 'die') {
      return isPlural
        ? { article: 'die', word, color: '#f97316', bgBadge: '#ffedd5' }
        : { article: 'die', word, color: '#ec4899', bgBadge: '#fce7f3' };
    }
    return { article: '', word: text, color: '#888', bgBadge: '#f3f4f6' };
  };

  const filteredMeat = animalsAndMeatData.filter((item) => {
    return (
      item.german.toLowerCase().includes(searchTerm.toLowerCase()) ||
      (item.plural && item.plural.toLowerCase().includes(searchTerm.toLowerCase())) ||
      item.arabic.includes(searchTerm)
    );
  });

  const meatCategoriesGrouped = [
    'الحيوانات واللحوم الأساسية',
    'الأجزاء والمنتجات الأخرى',
    'الشرائح والقطع والمنتجات الخاصة'
  ].reduce((acc, cat) => {
    acc[cat] = filteredMeat.filter((item) => item.category === cat);
    return acc;
  }, {});

  return (
    <div style={{ padding: '10px 10px 40px 10px', color: 'inherit', background: 'transparent', boxSizing: 'border-box', width: '100%' }}>
      <style>{`
        .page-container {
          background: transparent;
          width: 100%;
          max-width: 500px;
          margin: 0 auto;
          box-sizing: border-box;
        }

        .page-title {
          text-align: center;
          font-size: 1.25rem;
          font-weight: bold;
          margin-bottom: 12px;
          color: inherit;
        }

        .search-container {
          display: flex;
          justify-content: center;
          margin-bottom: 12px;
        }

        .search-input {
          width: 100%;
          padding: 8px 14px;
          border-radius: 20px;
          border: 1.5px solid currentColor;
          background: transparent;
          color: inherit;
          font-size: 0.9rem;
          outline: none;
          box-sizing: border-box;
          direction: rtl;
        }

        .articles-legend {
          display: flex;
          justify-content: center;
          flex-wrap: wrap;
          gap: 10px;
          font-size: 0.72rem;
          font-weight: bold;
          margin-bottom: 12px;
        }

        .legend-item {
          display: flex;
          align-items: center;
          gap: 4px;
        }

        .legend-dot {
          width: 8px;
          height: 8px;
          border-radius: 50%;
          display: inline-block;
        }

        .level-section-title {
          width: 100%;
          text-align: center;
          font-size: 1rem;
          font-weight: bold;
          margin: 22px 0 12px 0;
          padding: 5px;
          border-bottom: 2px dashed currentColor;
          opacity: 0.9;
        }

        /* شبكة من عمودين متساوين تماماً زي الصورة */
        .cards-grid {
          display: grid;
          grid-template-columns: repeat(2, 1fr);
          gap: 12px;
          width: 100%;
          direction: ltr;
        }

        /* تصميم الكارت الواحد مطابق للصورة تماماً */
        .single-card {
          position: relative;
          background-color: #ffffff;
          border-radius: 30px 6px;
          padding: 12px 8px 14px 8px;
          display: flex;
          flex-direction: column;
          align-items: center;
          text-align: center;
          box-shadow: 0 4px 10px rgba(0, 0, 0, 0.08);
          box-sizing: border-box;
          cursor: pointer;
          transition: transform 0.15s ease;
          user-select: none;
        }

        .single-card:active {
          transform: scale(0.97);
        }

        /* الهيدر العلوي جوه الكارت: شارة الأداة في النص والسماعة على اليمين */
        .card-top-bar {
          position: relative;
          width: 100%;
          display: flex;
          justify-content: center;
          align-items: center;
          margin-bottom: 10px;
          height: 22px;
        }

        .article-pill {
          padding: 2px 14px;
          border-radius: 12px;
          font-size: 0.72rem;
          font-weight: 800;
          text-transform: uppercase;
          letter-spacing: 0.5px;
        }

        .speaker-btn {
          position: absolute;
          right: 4px;
          top: 50%;
          transform: translateY(-50%);
          font-size: 1rem;
          color: #9ca3af;
          display: flex;
          align-items: center;
          justify-content: center;
        }

        /* حاوية الصورة المربعة بحواف ناعمة */
        .img-wrapper {
          width: 90px;
          height: 90px;
          border-radius: 16px;
          background-color: #ffffff;
          box-shadow: 0 2px 8px rgba(0, 0, 0, 0.06);
          display: flex;
          align-items: center;
          justify-content: center;
          overflow: hidden;
          margin-bottom: 10px;
        }

        .item-image {
          width: 100%;
          height: 100%;
          object-fit: cover;
        }

        /* الكلمة الألماني المفرد */
        .german-singular {
          font-size: 0.95rem;
          font-weight: 800;
          font-style: italic;
          line-height: 1.3;
          direction: ltr;
        }

        /* الكلمة الألماني الجمع تحتها */
        .german-plural {
          font-size: 0.85rem;
          font-weight: 800;
          font-style: italic;
          line-height: 1.3;
          margin-top: 2px;
          direction: ltr;
        }

        /* الترجمة العربي في الأسفل */
        .arabic-word {
          font-size: 0.82rem;
          font-weight: bold;
          color: #555555;
          margin-top: 6px;
          direction: rtl;
        }
      `}</style>

      <div className="page-container">
        <h1 className="page-title">قائمة الحيوانات واللحوم والشرائح</h1>

        {/* حقل البحث */}
        <div className="search-container">
          <input
            type="text"
            placeholder="ابحث عن حيوان أو نوع لحم أو شريحة..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="search-input"
          />
        </div>

        {/* دليل ألوان الأدوات */}
        <div className="articles-legend" dir="rtl">
          <span className="legend-item"><span className="legend-dot" style={{ backgroundColor: '#00bfff' }}></span> der (مذكر)</span>
          <span className="legend-item"><span className="legend-dot" style={{ backgroundColor: '#22c55e' }}></span> das (محايد)</span>
          <span className="legend-item"><span className="legend-dot" style={{ backgroundColor: '#ec4899' }}></span> die (مفرد مؤنث)</span>
          <span className="legend-item"><span className="legend-dot" style={{ backgroundColor: '#f97316' }}></span> die (جمع)</span>
        </div>

        {/* عرض الأقسام والكروت بنظام عمودين */}
        {Object.keys(meatCategoriesGrouped).map((cat) => {
          const items = meatCategoriesGrouped[cat];
          if (items.length === 0) return null;

          return (
            <React.Fragment key={cat}>
              <div className="level-section-title">{cat}</div>
              <div className="cards-grid">
                {items.map((item) => {
                  const singularInfo = getArticleStyle(item.german, false);
                  const pluralInfo = item.plural ? getArticleStyle(item.plural, true) : null;

                  return (
                    <div
                      key={item.id}
                      className="single-card"
                      style={{ border: `2.5px solid ${singularInfo.color}` }}
                      onClick={() => speakGerman(item.plural ? `${item.german}, ${item.plural}` : item.german)}
                    >
                      {/* الشريط العلوي: شارة الأداة + أيقونة السماعة */}
                      <div className="card-top-bar">
                        {singularInfo.article && (
                          <span
                            className="article-pill"
                            style={{
                              color: singularInfo.color,
                              backgroundColor: singularInfo.bgBadge
                            }}
                          >
                            {singularInfo.article}
                          </span>
                        )}
                        <span className="speaker-btn">🔊</span>
                      </div>

                      {/* الصورة */}
                      <div className="img-wrapper">
                        <img src={item.img} alt={item.arabic} className="item-image" />
                      </div>

                      {/* الكلمة المفرد (الأداة ملونة والكلمة أسود) */}
                      <div className="german-singular">
                        <span style={{ color: singularInfo.color }}>{singularInfo.article}</span>{' '}
                        <span style={{ color: '#000000' }}>{singularInfo.word}</span>
                      </div>

                      {/* الكلمة الجمع تحتها بالبرتقالي لو موجودة */}
                      {pluralInfo && (
                        <div className="german-plural">
                          <span style={{ color: '#f97316' }}>{pluralInfo.article}</span>{' '}
                          <span style={{ color: '#000000' }}>{pluralInfo.word}</span>
                        </div>
                      )}

                      {/* الترجمة بالعربي */}
                      <div className="arabic-word">{item.arabic}</div>
                    </div>
                  );
                })}
              </div>
            </React.Fragment>
          );
        })}
      </div>
    </div>
  );
}